"Darstellungsqualität":"Качество отображения",
"Das Bild konnte nicht gelesen werden.":"Не удалось прочитать изображение.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Изображение лежит на плоскости как подложка. Размер, положение, поворот и непрозрачность затем задаются в окне свойств (например, ширина по известному размеру).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Результат геометрического ядра нечитаем",
"Das Ergebnis konnte nicht geschrieben werden":"Не удалось записать результат",
"Das Maß muss größer als 0 sein.":"Размер должен быть больше 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Сетка остаётся треугольной сеткой (не B-Rep). Редактирование на вкладке СЕТКА: исправление, упрощение, сглаживание, сечение плоскостью … 3D-стратегии фрезерования в «Производстве» могут обрабатывать её напрямую.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Профиль не должен пересекать ось. Осью может служить незамкнутая линия эскиза.",
"Das Profil mit den jetzigen Werten überschreiben":"Перезаписать профиль текущими значениями",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Профиль проводится вдоль линии/ломаной. Профиль лучше чертить перпендикулярно началу траектории (например, профиль на XZ, траектория на XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Профиль выдавливается от плоскости эскиза выпукло или углублённо.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Заготовка — параллелепипед вокруг выбранного тела (плюс смещение).",
"Das Setup hat keine Operationen.":"В установе нет операций.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Инструмент фрезерует по окружностям, центр которых перемещается вдоль паза. Он никогда не находится в зацеплении всей шириной – это допускает большую глубину резания и щадит фрезу и шпиндель. Диаметр фрезы должен составлять около 60 % ширины паза.",
"Das Werkzeug schneidet die Fläche nicht":"Режущий объект не пересекает поверхность",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Инструмент режет в направлении выбранных граней, пока не достигнет заданных припусков.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Инструмент врезается вертикально, как сверло, ряд за рядом, до модели плюс припуск. Сила резания действует вдоль шпинделя: подходит для длинных инструментов, глубоких полостей и маложёстких станков. Инструмент должен резать через центр.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Инструмент избегает этих граней с учётом заданных безопасных зазоров (прихваты, тиски).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Инструмент избегает этих граней при обработке соседних и соблюдает безопасные зазоры.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Первое нажатие Esc отменяет только инструмент или выбор – лишнее нажатие Esc не закроет эскиз",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Это не отверстие (скругление или бобышка) – щёлкните внутреннюю стенку отверстия.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Это не отверстие (цилиндрическая грань) – щёлкните стенку отверстия.",
"Das ist keine WerkFab-Design-Datei.":"Это не файл темы WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Это не наклонное ребро – щёлкните оба конца ребра фаски.",
"Datei":"Файл",
