"Datum/Uhrzeit":"Дата/время",
"Deaktivieren":"Отключить",
"Deckkraft":"Непрозрачность",
"Deckkraft der Fenster":"Непрозрачность окон",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Диаметр стал бы нулевым или отрицательным – уменьшите расстояние",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Резьбовая фреза работает в полном материале: сначала обработайте цапфу (2D-контур снаружи вокруг цапфы до глубины резьбы).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"У тела нет контура на этой плоскости.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Тело сканируется вокруг своей вертикальной центральной оси и сохраняется как контур державки (участки) в библиотеке инструментов документа.",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Точка, вокруг которой вращается вид (при свободной орбите). «Под курсором мыши»: место модели, с которого начинается вращение.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Радиус равномерно растёт от начала к концу каждого выбранного ребра. Какой конец является началом, определяется ребром – при необходимости поменяйте.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Граница грани – замкнутая цепочка: с опцией «непрерывно» радиус проходит один раз по всему периметру, без неё – на каждом ребре отдельно от начального до конечного радиуса.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Вырез не затрагивает ни одно тело – материал не удаляется.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Текст записывается как комментарий в этом месте программы.",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Первое расстояние отмеряется на грани, которая больше направлена вверх (Z); второе расстояние или угол относится к другой грани. «Поменять стороны» меняет это местами. Касательно примыкающие рёбра включаются автоматически.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Выбранное тело является заготовкой (например, отливка или поковка). Само оно не обрабатывается.",
"Der große Geometriekern ist noch nicht geladen":"Полное геометрическое ядро ещё не загружено",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"Загружается полное геометрическое ядро – этот шаг через мгновение пересчитается сам",
