"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Повернуть: выберите элементы, затем щёлкните центр поворота и укажите угол мышью (предпросмотр); также с копированием",
