"Drehen: Gewindezyklus":"Точение: цикл нарезания резьбы",
"Drehen: Polar-Interpolation aus":"Точение: полярная интерполяция выкл.",
"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"Точение: полярная интерполяция вкл. (X – диаметр, C в мм; пусто = X/C в градусах)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"Точение: чистовой цикл (контур чернового цикла)",
"Drehen: Schruppzyklus ({contour} = Konturzeilen)":"Точение: черновой цикл ({contour} = строки контура)",
"Drehen: Vorsatz erste Konturzeile":"Точение: префикс первой строки контура",
"Drehen: Vorsatz letzte Konturzeile":"Точение: префикс последней строки контура",
"Drehen: Winkel (°, gegen den Uhrzeigersinn); Drehpunkt X; Drehpunkt Y; Kopien (0 = drehen)":"Повернуть: угол (°, против часовой стрелки); центр поворота X; центр поворота Y; копии (0 = повернуть)",
"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Точение: Z перед торцом, на котором поворачивается револьверная головка. 0 = безопасное расстояние + 100 mm",
