"Ebene Flächen des Körpers werden entlang ihrer Normalen extrudiert. Automatisch: nach außen = Material hinzufügen, nach innen (negativ) = ausschneiden.":"Плоские грани тела выдавливаются вдоль своих нормалей. Автоматически: наружу = добавить материал, внутрь (отрицательное значение) = вырезать.",
