"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Свои сочетания клавиш: откройте на панели инструментов меню группы (▾), щёлкните ⋮ у команды → «Изменить сочетание клавиш …».",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Собственные размеры и примечания можно перетаскивать мышью на листе (отступ размерной линии, угол линии-выноски, радиус дуги углового размера). Щелчок по двум углам = линейный размер. Щелчок по краю окружности на виде сверху = диаметр (или радиус). Угол: сначала вершина, затем по одной угловой точке на обеих сторонах. Фаска: оба конца наклонного ребра – получится, напр., 2×45°. В текстовом поле после каждого размера указывается дополнение, например ±0,1, H7 или 4×.",
