"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Круглая фреза оставляет в каждом внутреннем углу свой радиус – угловая сопрягаемая деталь тогда не войдёт. Выборка в каждом остром внутреннем углу ненадолго заходит в угол и возвращается.{0}{1}",
