"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Для лофта нужны два эскиза с замкнутыми профилями на разных плоскостях.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Для лофта нужны два эскиза с одной кривой в каждом (на разных плоскостях).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Лофт невозможен – проверить сечения (по одному замкнутому профилю, без скручивания)",
"Erhebung nicht möglich – je Skizze eine Kurve, gleiche Richtung, nicht verdreht":"Лофт невозможен – по одной кривой на эскиз, одно направление, без скручивания",
"Ersetzt den Standard-Kurzbefehl „{0}“.":"Заменяет стандартное сочетание «{0}».",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Сначала щёлкните грань на перемещаемом теле, затем целевую грань на другом теле. Тело поворачивается и перемещается, пока первая точка щелчка не совпадёт со второй и грани не лягут друг на друга.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Сначала щёлкните ребро на перемещаемом теле, затем целевое ребро на другом теле. Прямые рёбра совмещаются (середина с серединой); у круговых рёбер – отверстия и цапфы – оси направляются одинаково, а центры совмещаются.",
"Erst ein Setup anlegen.":"Сначала создать установ.",
"Erst ein Setup mit Operationen anlegen.":"Сначала создайте установ с операциями.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Сначала выберите эскиз или вспомогательную плоскость – тогда Ctrl+8 направит взгляд перпендикулярно на неё.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Сначала создайте тело в разделе ПРОЕКТИРОВАНИЕ или вставьте сетку (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Сначала создайте тело в разделе ПРОЕКТИРОВАНИЕ.",
"Erst einen Namen für das Profil eingeben.":"Сначала введите название профиля.",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"Сначала щёлкнуть в шаблоне, затем выбрать подстановку",
