"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Щёлкните грань тела: её граница попадёт в эскиз как контур. Щелчок по ребру проецирует только это ребро (окружности остаются окружностями). Спроецированная геометрия фиолетовая.",
