"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Грани на конце детали (две лыски, квадрат, шестигранник) приводной концевой фрезой вдоль Z. Размер под ключ = удвоенное расстояние грани от оси вращения. X и C движутся совместно (полярная интерполяция, Fanuc G12.1); без этого шаблона в постпроцессоре выводятся короткие шаги X/C.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Щёлкните грани для придания толщины (повторный щелчок снимает выбор).",
