"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"Для тачпадов: прокрутка сдвигает вид, разведение пальцев (или Ctrl + колесо мыши) масштабирует",
