"Für diese Strategie nicht geeignet":"Не подходит для этой стратегии",
"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Для наклонных направлений создайте вспомогательную ось (через две точки, цилиндр или две плоскости) – она появится здесь как направление.",
