"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Из каждого эскиза берётся первая кривая – незамкнутая или замкнутая. Кривые соединяются оболочкой (поверхность без толщины).",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Каждая ось отдельно: щёлкнуть ребро, вершину, грань или отверстие. Незаданные оси берутся из точки заготовки.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Каждая операция как подпрограмма (LBL) в конце программы, вызов через CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Каждая окружность эскиза — центр отверстия. Сверление идёт против нормали эскиза (в материал).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Каждая окружность эскиза повторяется с поворотом вокруг центра (в координатах эскиза) – окружность на расстоянии радиуса делительной окружности даёт окружность отверстий.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Каждая окружность эскиза превращается в сетку: шаги по X и Y эскиза (допускаются отрицательные).",
