"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Контур из {0} точек – Okuma: G85 (LAP) с контуром G81…G80, Fanuc: G71 P…Q…. Система ЧПУ выполняет черновую обработку со своим разбиением проходов; симуляция здесь – траектория WerkFab.",
"Kontur zum Freifräsen davor anlegen":"Создать предварительный контур для расчистки",
"Konturauswahl":"Выбор контура",
"Konturen außen und innen":"Внешние и внутренние контуры",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Контуры идут по границе тёмных областей. Осевая линия проходит по середине штрихов – подходит для гравировки и штриховых рисунков. «Прямые, дуги и окружности» распознаёт прямые края, острые углы, скругления и окружности; «Ломаные» повторяют изображение точка за точкой. Затем при необходимости подгоните масштаб командой «Откалибровать подложку» или «Масштабировать».",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Контуры с коррекцией на радиус в системе ЧПУ (RL/RR) подводятся и отводятся через APPR/DEP; система ЧПУ сама рассчитывает вспомогательную точку и коррекцию",
