"Kurven":"Кривые",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Кривые эскиза на торце (поперёк оси вращения) приводной фрезой вдоль Z (X и C движутся совместно; Fanuc: полярная интерполяция G12.1). Незамкнутые кривые фрезеруются туда и обратно. Глубина от торца.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Кривые эскиза, лежащего вдоль оси вращения, наматываются на окружность и фрезеруются приводной фрезой, направленной к оси (Z и C движутся совместно; Fanuc: цилиндрическая интерполяция G7.1). Плоскость эскиза задаёт угол, на котором находится контур; горизонтальные отрезки эскиза становятся дугами вокруг детали. Глубина от наружного диаметра.",
"Kurzbefehl":"Сочетание клавиш",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Короткие перемещения (до расстояния без отвода) инструмент проходит внизу на подаче перехода, а не через высоту отвода – без проверки столкновений, поэтому задавать малым.",
