"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Подвести мышь к контуру (сторона задаёт направление) · Esc – завершить",
"Mit diesem Werkzeug kann nicht gefräst werden":"Этим инструментом нельзя фрезеровать",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"С метчиком только цикл «Нарезание резьбы метчиком» – цикл сверления его сломает",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"При нескольких проходах глубина резьбы фрезеруется ступенями, каждая из которых снимает примерно одинаковый слой – это щадит малые резьбовые фрезы и твёрдые материалы. Выхаживающий проход повторяет последнюю траекторию ещё раз без подачи на глубину.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"При включённых «Циклах сверления» в управляющей программе выводятся циклы системы ЧПУ (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), иначе – развёрнутые перемещения.",
