"Noch keine Operation":"Операций пока нет",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Шаблонов пока нет. Шаблон сохраняет стратегии со всеми параметрами (инструмент, режимы резания, высоты, проходы, переходы) для повторного использования в других установах и проектах.",
