"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Циклом системы ЧПУ выполняются только наружные контуры (бобышки)",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Только диаметр (форма как у этого инструмента)",
