"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Циклом системы ЧПУ выполняются только прямоугольные и круглые карманы",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Обрабатывать только то, что фреза большего диаметра оставила в углах.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Проходить только те участки контура, которых не достигла фреза большего диаметра (внутренние углы, узкие места). Без дуг подвода/отвода, перемычек и чистовых проходов; коррекция в компьютере.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Только там, куда опорный инструмент не дошёл: пологие области – параллельно, крутые области – по ватерлинии. С инструментом из списка учитывается и его форма – например, что тороидальная фреза оставляет в галтелях.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Плоскостью эскиза могут служить только плоские грани.",
"Nur ebene Flächen können extrudiert werden":"Выдавливать можно только плоские грани",
"Nur ebene Flächen lassen sich ersetzen":"Заменять можно только плоские грани",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Смещать можно только плоские и цилиндрические грани (отверстия, цапфы)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Только плоские грани, обращённые вверх к инструменту (горизонтальные в этом установе).",
"Nur für Außen-Drehmeißel":"Только для наружных токарных резцов",
"Nur in Operationen verwendete":"Только используемые в операциях",
"Nur in diesem Projekt":"Только в этом проекте",
