"Nut liegt nicht am Teil":"Паз находится вне детали",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Паз вдоль оси вращения (напр. шпоночный) приводной фрезой, направленной к оси; главный шпиндель удерживает деталь как ось C. Ширина паза = Ø фрезы. Начало/конец Z – в Z модели; если паз доходит до торца, фреза входит спереди, иначе врезается в начале. Глубина от наружного диаметра.",
