"Offene Flächen":"Открытые грани",
"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Открытые рёбра показаны красным. «Исправить» закрывает отверстия.",
"Offene Linie in einer Skizze wählen":"Выбрать незамкнутую линию в эскизе",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Незамкнутые или замкнутые кривые вытягиваются перпендикулярно эскизу – получается поверхность (стенка без толщины). «Придать толщину» или «Сшить» превращает её в твёрдое тело.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Незамкнутые или замкнутые кривые вращаются вокруг оси – получается поверхность, а не твёрдое тело.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Без своей клавиши действует стандартная «{0}».",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Без «Смоделированная» резьба только изображается (быстро). При моделировании профиль резьбы действительно вырезается, например для 3D-печати. Отверстие под M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP, точение",
"Okuma OSP-M Fräsen":"Okuma OSP-M, фрезерование",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 там не перемещают в координаты станка (G53 отменяет коррекцию на длину инструмента) – отвод на безопасную высоту, выход в ноль XY не выводится",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: функция сглаживания не выводится (G5.1 – это Fanuc) – настройте Hi-Cut/Super-NURBS на станке",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: корректор+инструмент+кромка (напр. 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade (все функции)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: все функции. Ядро Rust (truck, экспериментальное): примитивы, выдавливание, вращение, отверстие, массив, зеркало, перемещение, масштабирование, объединение и экспорт STEP – остальные элементы помечаются как «пока не поддерживается».",
