"Positiv":"Положительное",
"Positiv = nach außen (mehr Material), negativ = nach innen. Ebene Flächen verschieben sich; bei einer Bohrung oder einem Zapfen ändert sich der Radius um den Abstand – eine Bohrung wird mit positivem Abstand enger.":"Положительное = наружу (больше материала), отрицательное = внутрь. Плоские грани сдвигаются; у отверстия или цапфы радиус изменяется на величину смещения – отверстие при положительном смещении становится уже.",
"Positiver Abstand = in Richtung der Skizzennormalen. Taschen: Ausschneiden mit negativem Abstand.":"Положительное расстояние = в направлении нормали эскиза. Карманы: вырезание с отрицательным расстоянием.",
