"Rechteck- und Kreistaschen ohne Inseln gehen als Zyklus der Steuerung (Heidenhain 251/252).":"Прямоугольные и круглые карманы без островов выводятся как цикл системы ЧПУ (Heidenhain 251/252).",
"Rechteck-/Kreistasche erkannt ({0}) – Heidenhain: CYCL DEF 251/252 an der Taschenmitte. Die Steuerung fräst mit ihrer eigenen Strategie; Simulation und Bahn hier sind die WerkFab-Bahn.":"Распознан прямоугольный/круглый карман ({0}) – Heidenhain: CYCL DEF 251/252 в центре кармана. Система ЧПУ фрезерует по собственной стратегии; симуляция и траектория здесь – траектория WerkFab.",
