"Rechteck-Muster: Anzahl X; Abstand X; Anzahl Y; Abstand Y (mm) – bei Anzahl Y = 1 liegen die Kopien in Richtung des gezeigten Abstands":"Прямоугольный массив: количество X; шаг X; количество Y; шаг Y (мм) – при количестве Y = 1 копии располагаются в направлении указанного расстояния",
"Rechteck-Muster: mit der Maus den Abstand der ersten Kopie zeigen (Vorschau) und klicken. Esc beendet.":"Прямоугольный массив: укажите мышью расстояние до первой копии (предпросмотр) и щёлкните. Esc – завершить.",
