"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Карман в торце по замкнутым контурам эскиза (внутренние контуры остаются островами), приводной концевой фрезой вдоль Z. Выборка идёт изнутри наружу; фреза врезается наклонно вдоль самого внутреннего прохода и в пределах одного уровня остаётся внизу. X и C движутся совместно (Fanuc: полярная интерполяция G12.1). Глубина от торца.",
