"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Наматывает кривые эскиза на цилиндр: X остаётся X, расстояние поперёк оси становится дугой на Ø намотки (поворот A). Эскиз должен быть параллелен оси A, напр. на касательной плоскости. Фрезерование идёт на постоянной глубине под поверхностью детали – для гравировок, надписей и пазов вокруг детали.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Как 3D-контур, но инструмент опускается непрерывно, без ступеней – без следов врезания на крутых стенках.",
