"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: нулевая точка Y/Z не лежит на оси вращения A (ось при Y{1} Z{2}) – для 4-осевой одновременной обработки поместите нулевую точку на ось (точка заготовки: центр Y/Z)",
"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0}: в постпроцессоре нет цикла точения – выведено как траектория",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0}: в постпроцессоре нет полярной интерполяции – поверхности выведены короткими шагами X/C (C в градусах); подача в зависимости от системы ЧПУ тогда не действует вдоль траектории. Лучше заполнить шаблон «Полярная интерполяция вкл./выкл.»",
"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: в постпроцессоре нет шаблона «Ось C и приводной инструмент вкл.» – включите ось C и шпиндель инструмента вручную",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: в постпроцессоре нет цилиндрической интерполяции – Z и C перемещаются совместно; подача в зависимости от системы ЧПУ тогда не действует вдоль траектории. Лучше заполнить шаблон «Цилиндрическая интерполяция вкл./выкл.»",
"{0}: Postprozessor ohne {1} für diese Form – als Bahn ausgegeben":"{0}: в постпроцессоре нет {1} для этой формы – выведено как траектория",
